import attr
from functools import cached_property

class Base:
    def __getattribute__(self, item):
        if item == "y":
            return "Base getattribute"
        return super().__getattribute__(item)
    def __getattr__(self, item):
        return "Base getattr"

@attr.s(slots=True)
class A(Base):
    @cached_property
    def x(self):
        return 1

a = A()
print(f"y: {a.y}")
